    @staticmethod
    def _entry(
        parent, label, var, row, unit,
        column_offset=0
    ):
        ttk.Label(
            parent, text=label + ":"
        ).grid(
            row=row,
            column=column_offset,
            sticky="w",
            padx=(0, 7),
            pady=4
        )

        entry = ttk.Entry(
            parent,
            textvariable=var,
            width=13
        )
        entry.grid(
            row=row,
            column=column_offset + 1,
            sticky="w",
            pady=4
        )

        ttk.Label(
            parent, text=unit
        ).grid(
            row=row,
            column=column_offset + 2,
            sticky="w",
            padx=(5, 18),
            pady=4
        )
        return entry

    def _color_selector(
        self, parent, label, variable, row
    ):
        ttk.Label(
            parent, text=label + ":"
        ).grid(
            row=row, column=0,
            sticky="w", padx=(0, 8), pady=5
        )

        btn = tk.Button(
            parent,
            text="  Seleccionar  ",
            width=14,
            bg=variable.get(),
            fg=best_text_color(variable.get()),
            activebackground=variable.get(),
            activeforeground=best_text_color(
                variable.get()
            ),
            relief="solid",
            bd=1,
            highlightthickness=0,
            padx=8,
            pady=5,
            font=("Segoe UI Semibold", 10),
            cursor="hand2"
        )
        btn.grid(
            row=row, column=1,
            sticky="w", pady=5
        )

        ttk.Label(
            parent,
            textvariable=variable,
            width=10
        ).grid(
            row=row, column=2,
            sticky="w",
            padx=(8, 0),
            pady=5
        )

        def choose():
            _, chosen = colorchooser.askcolor(
                color=variable.get(),
                parent=self,
                title=_tr_text(label)
            )
            if chosen:
                variable.set(chosen.upper())
                btn.configure(
                    bg=variable.get(),
                    fg=best_text_color(
                        variable.get()
                    ),
                    activebackground=variable.get(),
                    activeforeground=best_text_color(
                        variable.get()
                    )
                )
                self.refresh_active_preview()

        btn.configure(command=choose)
        self._color_selector_widgets.append((btn, variable))
        return btn

    def _build_on(self):
        s = self.saved.get("on_off", {})

        self.on_baseline = tk.StringVar(
            value=str(
                s.get("baseline_s", 2.0)
            )
        )
        self.on_on = tk.StringVar(
            value=str(
                s.get(
                    "on_s",
                    s.get("white_s", 2.0)
                )
            )
        )
        self.on_gray = tk.StringVar(
            value=str(
                s.get("gray_interval_s", 2.0)
            )
        )
        self.on_off = tk.StringVar(
            value=str(
                s.get(
                    "off_s",
                    s.get("black_s", 2.0)
                )
            )
        )
        self.on_final = tk.StringVar(
            value=str(
                s.get("final_gray_s", 2.0)
            )
        )
        self.on_reps = tk.StringVar(
            value=str(
                s.get("repetitions", 5)
            )
        )

        # A standard ON/OFF experiment is simply the default:
        # ON = white and OFF = black. Changing either selector turns
        # the same stimulus into a chromatic ON/OFF paradigm.
        self.on_on_hex = tk.StringVar(
            value=str(
                s.get("on_hex", "#FFFFFF")
            ).upper()
        )
        self.on_off_hex = tk.StringVar(
            value=str(
                s.get("off_hex", "#000000")
            ).upper()
        )

        controls = self._make_tab_layout(
            self.tab_on,
            "on_off",
            "ON / OFF"
        )

        g = ttk.Frame(
            controls, style="Card.TFrame"
        )
        g.pack(
            anchor="nw",
            fill="x",
            padx=16,
            pady=16
        )

        ttk.Label(
            g,
            text=(
                "adaptación → ON → adaptación → "
                "OFF → adaptación"
            ),
            font=("Segoe UI Semibold", 11)
        ).grid(
            row=0,
            column=0,
            columnspan=3,
            sticky="w",
            pady=(0, 10)
        )

        ttk.Label(
            g,
            text=(
                "Blanco y negro son los colores predeterminados. "
                "Puedes cambiarlos directamente para realizar el mismo "
                "paradigma con cualquier pareja de colores."
            ),
            style="Muted.TLabel",
            wraplength=720
        ).grid(
            row=1,
            column=0,
            columnspan=3,
            sticky="w",
            pady=(0, 10)
        )

        self._entry(
            g, "Adaptación inicial",
            self.on_baseline, 2, "s"
        )
        self._entry(
            g, "Duración ON",
            self.on_on, 3, "s"
        )
        self._entry(
            g, "Adaptación intermedia",
            self.on_gray, 4, "s"
        )
        self._entry(
            g, "Duración OFF",
            self.on_off, 5, "s"
        )
        self._entry(
            g, "Adaptación final",
            self.on_final, 6, "s"
        )
        self._entry(
            g, "Repeticiones",
            self.on_reps, 7, ""
        )

        self._color_selector(
            g, "Color ON",
            self.on_on_hex, 8
        )
        self._color_selector(
            g, "Color OFF",
            self.on_off_hex, 9
        )

        ttk.Label(
            g,
            text=(
                "Estado basal y periodos intermedios: fondo de adaptación. "
                "TTL: un pulso al inicio de ON y otro al inicio de OFF."
            ),
            style="Muted.TLabel",
            wraplength=720
        ).grid(
            row=10,
            column=0,
            columnspan=3,
            sticky="w",
            pady=(8, 0)
        )

